  const p1=`${range}: “${event||title}” என்பது ${title} பகுதியில் முதன்மை நடைமுறை வெளிப்பாடு; குறிப்பாக ${focus} எப்படி மாறுகிறது என்பதைக் கொண்டு இதை மதிப்பிட வேண்டும். ${dasha}${trans}`.replace(/\s+/g,' ').trim();
