  const key=`${z.start}–${z.end}`;const stateTone=state==='support'?`${key} கல்விக் கட்டத்தில் அந்த வயதுக்குரிய கற்றல் திறன் வளர உதவும் ஆதரவு அதிகம்.`:state==='pressure'?`${key} கல்விக் கட்டத்தில் மந்தம், ஆர்வக் குறைவு, கவனச்சிதறல் அல்லது முறையை மாற்ற வேண்டிய தேவை வரலாம்; பிறப்பு capacity அழிந்தது என்று வாசிக்கக்கூடாது.`:`${key} கல்விக் கட்டம் சுமாரான/மாறுபட்ட பலன் தரலாம்; சூழல், ஆசிரியர், routine மற்றும் உடல்நிலை எவ்வாறு இருக்கிறது என்பதே performance-ஐ அதிகம் மாற்றும்.`;
  const inter=v252HealthStudyInterference(e,z.start,z.end,lang);rows.push(`${z.start} → ${z.end} (வயது ${age}): ${v252StageLabel(age,lang)}. ${stageTone} ${v251Planet(z.md,lang)}–${v251Planet(z.ad,lang)} காலத்தில் ${ev?`“${ev}” அருகிலுள்ள கற்றல் வெளிப்பாடாக செயல்படுகிறது. `:''}${stateTone}${health?` அதே காலத்தில் ${pickLang(health.title,lang)} சார்ந்த அழுத்தம் இருப்பதால் கல்வி capacity மற்றும் அன்றாட performance இரண்டையும் தனியாக மதிப்பிட வேண்டும்.`:''} ${inter}`.replace(/\s+/g,' ').trim());
